package br.com.bemdoar.service;
import br.com.bemdoar.dto.*;import br.com.bemdoar.entity.*;import br.com.bemdoar.enums.*;import br.com.bemdoar.exception.*;import br.com.bemdoar.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.time.LocalDateTime;import java.util.*;
@Service public class EvidenciaService{private final EvidenciaRepository repo;private final AcaoSocialRepository acoes;private final Path pastaUpload;public EvidenciaService(EvidenciaRepository r,AcaoSocialRepository a,@Value("${bemdoar.upload.diretorio:./uploads}")String diretorio){repo=r;acoes=a;pastaUpload=Paths.get(diretorio).toAbsolutePath().normalize();}
 @Transactional public EvidenciaResponse enviar(Long acaoId,MultipartFile f){if(repo.countByAcaoId(acaoId)>=5)throw new RegraNegocioException("Maximo de 5 evidencias por acao.");if(f.isEmpty()||f.getSize()>5*1024*1024)throw new RegraNegocioException("O arquivo deve ter no maximo 5 MB.");Map<String,TipoEvidencia> tipos=Map.of("image/jpeg",TipoEvidencia.JPEG,"image/png",TipoEvidencia.PNG,"application/pdf",TipoEvidencia.PDF);TipoEvidencia tipo=tipos.get(f.getContentType());if(tipo==null||!assinaturaValida(f,tipo))throw new RegraNegocioException("O conteudo do arquivo nao corresponde a JPEG, PNG ou PDF.");AcaoSocial a=acoes.findById(acaoId).orElseThrow(()->new RecursoNaoEncontradoException("Acao social nao encontrada."));Path destino=null;try{Files.createDirectories(pastaUpload);String nome=UUID.randomUUID()+"-"+Paths.get(Objects.requireNonNullElse(f.getOriginalFilename(),"arquivo")).getFileName();destino=pastaUpload.resolve(nome).normalize();if(!destino.startsWith(pastaUpload))throw new RegraNegocioException("Nome de arquivo invalido.");f.transferTo(destino);Evidencia e=new Evidencia();e.setAcao(a);e.setNomeArquivo(Objects.requireNonNullElse(f.getOriginalFilename(),"arquivo"));e.setTipo(tipo);e.setCaminho("/uploads/"+nome);e.setPublica(false);e.setDataUpload(LocalDateTime.now());return EvidenciaResponse.de(repo.save(e));}catch(Exception ex){if(destino!=null)try{Files.deleteIfExists(destino);}catch(Exception ignorado){}throw new RegraNegocioException("Nao foi possivel salvar o arquivo.");}}
 private boolean assinaturaValida(MultipartFile f,TipoEvidencia tipo){try{byte[] b=f.getInputStream().readNBytes(8);return switch(tipo){case JPEG->b.length>=3&&(b[0]&255)==0xFF&&(b[1]&255)==0xD8&&(b[2]&255)==0xFF;case PNG->b.length>=8&&(b[0]&255)==0x89&&b[1]==0x50&&b[2]==0x4E&&b[3]==0x47&&b[4]==0x0D&&b[5]==0x0A&&b[6]==0x1A&&b[7]==0x0A;case PDF->b.length>=4&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F';};}catch(Exception e){return false;}}
 @Transactional public EvidenciaResponse visibilidade(Long id){Evidencia e=repo.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Evidencia nao encontrada."));e.setPublica(!e.isPublica());return EvidenciaResponse.de(repo.save(e));}
 @Transactional public void excluir(Long id){Evidencia e=repo.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Evidencia nao encontrada."));repo.delete(e);String nome=Paths.get(e.getCaminho()).getFileName().toString();try{Files.deleteIfExists(pastaUpload.resolve(nome).normalize());}catch(Exception ex){throw new RegraNegocioException("Registro removido, mas o arquivo nao pode ser excluido.");}}
}
